node <<'NODE'
const fs=require('fs');
const m=JSON.parse(fs.readFileSync('docs/EVENT_MANIFEST.json','utf8'));
const out={};
for(const e of m.events){
  const y=(e.historicalDate||'').match(/(20\d{2})/);
  const year=y?y[1]:'unknown';
  out[year]=out[year]||{count:0,grades:{A:0,B:0,C:0,R:0,other:0}};
  out[year].count++;
  const g=(e.proseGrade||'other');
  if(out[year].grades[g]===undefined) out[year].grades.other++;
  else out[year].grades[g]++;
}
for(const y of Object.keys(out).sort()){
  const r=out[y];
  console.log(`${y}\tcount=${r.count}\tA=${r.grades.A}\tB=${r.grades.B}\tC=${r.grades.C}\tR=${r.grades.R}\tother=${r.grades.other}`);
}
